#include "eternity/game/account_state.hpp"
#include "eternity/game/interface_save.hpp"
#include "eternity/game/quest_save.hpp"
#include "eternity/game/skill_save.hpp"
#include "eternity/game/character_core_save.hpp"
#include "eternity/game/inventory_save.hpp"
#include "eternity/game/creation.hpp"
#include <iostream>

using namespace eternity;using namespace eternity::game;
namespace {
void require(bool value,const char* message) {if(!value) throw std::runtime_error(message);}
void put(net::Packet& p,std::uint32_t value,unsigned int count) {for(unsigned int i=0;i<count;++i) p.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
net::Packet packet(std::uint16_t op) {net::Packet p;put(p,op,2);put(p,9501,4);return p;}
net::Packet market(std::initializer_list<std::uint32_t> ids) {auto p=packet(0x61a);p.push_back(static_cast<std::uint8_t>(ids.size()));for(auto id:ids) put(p,id,4);return p;}
}
int main(int argc,char** argv) {
    try {
        require(argc==2 && std::string_view(argv[1]).starts_with("Eternity_Test_Creation_"),"Account state SQL test requires disposable catalog");const std::string catalog=argv[1],prefix="["+catalog+"].dbo.";
        const auto config=storage::SqlServerConfig::from_environment();storage::SqlServer db(config),grow_db(config);const auto definitions=Definitions::load(db);const auto rules=CreationRules::load(definitions);const auto time=std::chrono::sys_days{std::chrono::year{2024}/1/1};Characters characters(db,1,time,catalog);require(characters.save_country(9501,0,true) && characters.save_country(9502,0,true),"Cannot initialize account fixture factions");auto draft=rules.prepare({0,0,2,0,0,0,0,0,"StateHero"},0);draft.items.clear();const auto created=characters.create(9501,"state_user",draft,time);draft.request.name="StateOther";const auto other=characters.create(9502,"state_other",draft,time);require(created.result==0 && other.result==0,"Cannot create account fixture characters");const auto cid=std::to_string(created.character_id),other_id=std::to_string(other.character_id);
        db.query("EXEC "+prefix+"usp_Save_Char_ConcernMarket_Add_E "+cid+",100; EXEC "+prefix+"usp_Save_Char_ConcernMarket_Add_E "+other_id+",900;");
        PlayerSnapshot initial;initial.core.user_id=9501;initial.core.character=draft.character;initial.core.character.id=created.character_id;initial.core.character.level=30;initial.core.skill_points=40;initial.concern_market={100};InventoryReplicaPool pool;CharacterReplica cache(initial.core,pool);require(cache.market().load(initial),"Cannot load typed market state");cache.growth().load(2);
        GrowthStore grow(grow_db,1,catalog);MarketStore concerns(db,catalog);CharacterCoreStore core(db,catalog);InventoryStore items(db,1,catalog);SkillStore skills(db,catalog);QuestStore quests(db,catalog);InterfaceStore ui(db,catalog);unsigned int diagnostics=0;
        const auto apply=[&](const net::Packet& p){require(cache.apply(p)==InventoryReplicaResult::applied,"Account fixture command failed");};
        const auto save=[&](){core.save_in_transaction(cache);items.save_in_transaction(cache.inventory(),created.character_id);skills.save_in_transaction(cache.skills(),created.character_id);quests.save_in_transaction(cache.quests(),created.character_id);ui.save_in_transaction(cache.interface(),created.character_id,false);return concerns.save_in_transaction(cache.market(),created.character_id,[&](std::string_view text){require(!text.empty(),"Market diagnostic is empty");++diagnostics;});};
        const auto ack=[&](){cache.core_save_success();cache.inventory().inventory_save_success();cache.skills().save_success();cache.quests().save_success();cache.interface().save_success();};
        const auto read_market=[&](){return db.query("SELECT MarketID FROM "+prefix+"MarketCharConcern WHERE CharID="+cid+" ORDER BY MarketID;")[0].rows;};
        bool rejected=false;try{concerns.save_in_transaction(cache.market(),created.character_id);}catch(const std::logic_error&){rejected=true;}require(rejected,"Market phase ran outside character transaction");
        auto growth=grow.save(cache.growth(),9501,cache.core().character.grow,cache.core().character.level);require(growth.advanced && growth.legacy_code==0 && !growth.failure && cache.growth().maximum()==3,"Original hard-mode level-30 unlock failed");
        apply(market({200,201}));PlayerItem item;item.uid=0x7777000000000700ULL;item.id=5001;item.type=5;item.type_id=1;item.bag=1;item.count=10;item.made_at=pack_world_time(time);item.make_type="U";require(cache.inventory().load(item,false,1),"Cannot seed composite item");auto skill=packet(0x801);put(skill,20,2);put(skill,5,2);skill.push_back(1);apply(skill);auto quest=packet(0xa01);put(quest,10,2);put(quest,1,2);apply(quest);
        db.begin();auto result=save();require(!result.failure && cache.market().save_type()==0 && cache.inventory().inventory()[0].save_type==1,"Market marker did not clear before character commit");db.rollback();
        require(read_market()==std::vector<storage::Row>{{storage::Cell{"100"}}} && cache.market().save_type()==0 && cache.market().ids()[0]==200,"Rollback silently restored the original pre-commit market marker");auto rows=db.query("SELECT MaxGrow FROM "+prefix+"UserMaxGrow WHERE ServerID=1 AND UserUID=9501; SELECT [Level] FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT COUNT(*) FROM "+prefix+"CharItems WHERE CharID="+cid+";");require(rows[0].rows[0][0]==storage::Cell{"3"} && rows[1].rows[0][0]==storage::Cell{"1"} && rows[2].rows[0][0]==storage::Cell{"0"},"Growth did not commit independently of rolled-back character state");
        growth=grow.save(cache.growth(),9501,2,30);require(!growth.advanced && !growth.failure,"Confirmed growth was unnecessarily written again");db.begin();result=save();db.commit();ack();require(!result.failure && read_market()==std::vector<storage::Row>{{storage::Cell{"100"}}},"Retry incorrectly reconstructed the market state cleared before rollback");
        apply(market({300,2147483000,301}));auto money=packet(0x603);put(money,77,4);apply(money);auto count=packet(0x707);count.insert(count.end(),{1,0,4});apply(count);db.begin();result=save();require(result.failure && diagnostics==1 && cache.market().save_type()==1,"Market insert failure did not remain pending/nonfatal");db.commit();ack();require(read_market()==std::vector<storage::Row>{{storage::Cell{"300"}}} && cache.market().save_type()==1,"Original partial market list did not commit with pending retry");
        rows=db.query("SELECT Money FROM "+prefix+"Chars WHERE CharID="+cid+"; SELECT [Count] FROM "+prefix+"CharItems WHERE CharID="+cid+";");require(rows[0].rows[0][0]==storage::Cell{"77"} && rows[1].rows[0][0]==storage::Cell{"4"},"Market failure incorrectly rolled back core/item phases");
        apply(market({300,301,UINT32_MAX,0x80000000U}));db.begin();result=save();db.commit();ack();require(!result.failure && cache.market().save_type()==0 && read_market()==std::vector<storage::Row>{{storage::Cell{"-2147483648"}},{storage::Cell{"-1"}},{storage::Cell{"300"}},{storage::Cell{"301"}}},"Market retry lost signed DWORD IDs or pending state");
        apply(market({}));require(cache.market().save_type()==3 && !cache.market().packet(),"Empty market command did not request deletion/omit packet");db.begin();result=save();db.commit();ack();require(!result.failure && cache.market().save_type()==0 && read_market().empty(),"Market clear did not persist");rows=db.query("SELECT MarketID FROM "+prefix+"MarketCharConcern WHERE CharID="+other_id+";");require(rows[0].rows==std::vector<storage::Row>{{storage::Cell{"900"}}},"Market save reached a different character");
        // Growth failure retains the advanced cache value and does not automatically retry.
        const auto before=grow_db.query("SELECT MaxGrow FROM "+prefix+"UserMaxGrow WHERE ServerID=1 AND UserUID=9502;")[0].rows;GrowthReplica failed_grow(2);unsigned int grow_logs=0;auto failed=grow.save(failed_grow,9502,2,30,[&](std::string_view){++grow_logs;});require(failed.advanced && failed.legacy_code==0 && failed.failure && grow_logs==1 && failed_grow.maximum()==3,"Original growth API-error/cache contract changed");failed=grow.save(failed_grow,9502,2,30,[&](std::string_view){++grow_logs;});require(!failed.advanced && !failed.failure && grow_logs==1 && grow_db.query("SELECT MaxGrow FROM "+prefix+"UserMaxGrow WHERE ServerID=1 AND UserUID=9502;")[0].rows==before,"Failed growth unexpectedly retried or reverted its cache");
        GrowthReplica missing(2);const auto zero_rows=grow.save(missing,9503,2,30);require(zero_rows.advanced && !zero_rows.failure && zero_rows.legacy_code==0 && grow_db.query("SELECT COUNT(*) FROM "+prefix+"UserMaxGrow WHERE UserUID=9503;")[0].rows[0][0]==storage::Cell{"0"},"Original zero-row growth update was not accepted");
        GrowthStore wrong_connection(db,1,catalog);GrowthReplica unchanged(2);db.begin();rejected=false;try{wrong_connection.save(unchanged,9501,2,30);}catch(const std::logic_error&){rejected=true;}db.rollback();require(rejected && unchanged.maximum()==2,"Growth entered the character transaction or changed cache before rejecting misuse");
        std::cout<<"Original market/growth SQL passed: partial market commit/retry, pre-commit marker timing, signed IDs, independent unlock and failure cache behavior\n";
    }catch(const std::exception& error) {std::cerr<<error.what()<<'\n';return 1;}
}
